from pyspark.sql import functions as F


def solve(api_requests):
    salted = api_requests.select("*", F.pmod(F.hash("request_id"), F.lit(4)).alias("salt"))
    partial = salted.groupBy("endpoint", "salt").agg(
        F.count("*").alias("requests"),
        F.sum("latency_ms").alias("total_latency_ms"),
        F.max("latency_ms").alias("slowest_ms"),
    )
    return partial.groupBy("endpoint").agg(
        F.count("*").alias("requests"),
        F.sum("total_latency_ms").alias("total_latency_ms"),
        F.sum("slowest_ms").alias("slowest_ms"),
    )
